import * as X from './expansion.mjs';
import {renderNeighborhood,trainingCard} from './expansion-ui.mjs';
import * as E from './engine.mjs';
import {MOVIES,REGULARS,CANDIDATES,SNACKS,UPGRADES,EVENTS,GENRES} from './data.mjs';
import {StoreScene,crop} from './scene.mjs';
import {GameAudio} from './audio.mjs';
import {TabletUI} from './touch.mjs';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>`$${Number(n).toFixed(2)}`;
const KEY='movie-rental-empire-v1';let s,saveAvailable=true;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(E.validate(parsed))s=parsed;}}catch{saveAvailable=false;}
s=s||E.fresh();normalizeDecor();X.ensure(s);s.notices=[];let paused=true,speed=1,station='counter',tab='catalog',neighborhood='stories',genre='All',search='',ownedOnly=false,selectedCustomer=null,workSig='',lastPhase=s.phase,lastDay=s.day,last=0,acc=0,saveAcc=0,bizDirty=false;
function normalizeDecor(){const d=s.decor||{};s.decor={name:typeof d.name==='string'?d.name.slice(0,28):'Rewind & Dandy',sign:['rose','mint','gold'].includes(d.sign)?d.sign:'rose',plants:d.plants===true,rug:d.rug===true,arcade:d.arcade===true};}
const audio=new GameAudio(),modal=$('modal');const scene=new StoreScene($('scene'),roomAction);
const tablet=new TabletUI({onAction:action=>{if(action==='speed'){$('speedBtn').onclick();return;}if(s.phase!=='open'){openStore();return;}paused=!paused;updateHud();},onView:()=>{renderBusiness();updateHud();},message:toast});
let inputRefresh=0;function refreshAfterInput(){clearTimeout(inputRefresh);const refresh=()=>{if(tablet.pointerHeld){inputRefresh=setTimeout(refresh,100);return;}renderAll();};inputRefresh=setTimeout(refresh,100);}
function toast(text,type='info'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=text;$('toasts').appendChild(el);while($('toasts').children.length>3)$('toasts').firstElementChild.remove();setTimeout(()=>el.remove(),4700);}
function save(){try{const clean=JSON.stringify({...s,notices:[]});localStorage.setItem(KEY,clean);$('saveStatus').textContent='Saved on this device';saveAvailable=true;}catch{saveAvailable=false;$('saveStatus').textContent='Local save unavailable · export a backup in ☰';} }
function cover(m,extra=''){const [x,y,w,h]=crop(m.id);return `<div class="cover ${extra}" role="button" tabindex="0" data-action="movie" data-id="${m.id}" aria-label="Inspect ${esc(m.title)}"><div class="cover-art" style="background-size:${1122/w*100}% ${1402/h*100}%;background-position:${x/(1122-w)*100}% ${y/(1402-h)*100}%"></div><span class="genre-ribbon">${esc(m.genre)}</span><span class="cover-title">${esc(m.title)}</span></div>`;}
function showModal(html){$('modalContent').innerHTML=html;if(!modal.open)modal.showModal();}
function dismiss(){modal.close();}
function flush(){const notes=s.notices.splice(0);for(const n of notes.slice(-3)){toast(n.text,n.type);if(['sale','reward','rewind','customer'].includes(n.type))audio.fx(n.type==='customer'?'door':n.type);}if(notes.length)bizDirty=true;}
function floatCash(amount){const el=document.createElement('div');el.className='float';el.textContent=`+${money(amount)}`;$('floating').appendChild(el);setTimeout(()=>el.remove(),1300);}
function roomAction(id,customer){if(['catalog','snacks','decor','crew','upgrades','ledger','neighborhood','visitor','collections'].includes(id)){if(id==='visitor'||id==='collections'){neighborhood=id;tab='neighborhood';}else tab=id;tablet.setView('manage',{scroll:false});return;}setStation(id);if(customer){selectedCustomer=customer;workSig='';renderWork(true);if(id==='counter'){const card=$('workContent').querySelector(`[data-action="checkout"][data-id="${customer}"]`);card?.closest('.customer-card')?.scrollIntoView({block:'nearest'});}}}
function roomMenu(){showModal(`<div class="intro-banner">${esc(s.decor.name)} · DAY ${s.day}</div><h2>Your store</h2><div class="room-menu-grid"><button data-action="room-fullscreen">${document.fullscreenElement?'Exit full screen':'Full screen · landscape'}</button><button data-action="room-camera">Fit the whole store</button><button data-action="room-zoom">Closer view</button><button data-action="room-speed">Speed · ${speed}×</button><button data-action="room-manage" data-kind="catalog">Movie catalog</button><button data-action="room-manage" data-kind="crew">Employees & wages</button><button data-action="room-manage" data-kind="snacks">Snacks & prices</button><button data-action="room-manage" data-kind="upgrades">Equipment & expansion</button><button data-action="room-manage" data-kind="decor">Decorate & rename</button><button data-action="room-manage" data-kind="ledger">Goals & ledger</button><button data-action="room-manage" data-kind="neighborhood">Neighbors & movie nights</button><button data-action="room-help">How to play</button><button data-action="room-settings">Save & sound</button></div><p class="note">Drag the room to look around. Pinch to zoom. Tap a customer to serve them, or an object to manage it. Rotate your tablet sideways for the largest view.</p>`);}
function setStation(next){if(tablet.view!=='play')tablet.setView('play',{scroll:false});station=next;selectedCustomer=null;workSig='';document.querySelectorAll('[data-station]').forEach(b=>b.classList.toggle('active',b.dataset.station===station));renderWork(true);tablet.focusWork();audio.fx('click');}
function openStore(){tablet.setView('play');if(s.phase==='open'){paused=!paused;}else{E.openDay(s);paused=false;renderBusiness();}dismiss();renderAll();flush();save();}
function updateHud(){
 document.querySelector('.brand small').textContent=s.decor.name.toUpperCase();$('cash').textContent=money(s.cash);$('rep').innerHTML=`${Math.round(s.rep)} <span>/ 100</span>`;const days=['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY'];$('dayLabel').textContent=`${days[(s.day-1)%7]} · DAY ${s.day}`;let hour=16+Math.floor(s.seconds/60),min=Math.floor(s.seconds%60);$('clock').textContent=s.phase==='planning'?'Before opening':s.phase==='closed'?'Shift complete':`${hour%12||12}:${String(min).padStart(2,'0')} ${hour>=24?'AM':'PM'}`;
 $('openSign').textContent=s.phase==='open'?(paused||modal.open||tablet.managing?'PAUSED':'OPEN'):'CLOSED';$('openSign').classList.toggle('lit',s.phase==='open');$('openBtn').textContent=s.phase==='planning'?'Open the store →':s.phase==='closed'?`Open day ${s.day+1} →`:paused?'Resume shift ▶':'Shift in progress';$('openBtn').disabled=s.phase==='open'&&!paused;$('pauseBtn').disabled=s.phase!=='open';$('pauseBtn').textContent=paused?'▶':'Ⅱ';$('pauseBtn').setAttribute('aria-label',paused?'Resume shift':'Pause shift');$('speedBtn').textContent=speed+'×';
 const q=s.customers.filter(c=>c.stage==='checkout').length,h=s.customers.filter(c=>c.stage==='help').length,d=s.stock.reduce((a,v)=>a+v.dirty,0),sh=s.stock.reduce((a,v)=>a+v.shelve,0),o=E.overdue(s).filter(l=>!l.called).length;
 tablet.sync({phase:s.phase,paused,modal:modal.open,waiting:q+h,day:s.day,clock:$('clock').textContent,speed});
 $('roomCash').textContent=money(s.cash);$('roomTime').textContent=`Day ${s.day} · ${$('clock').textContent}`;$('roomGoal').textContent=`${s.daily.rentals}/${E.goal(s)} rentals`;$('roomPause').textContent=s.phase!=='open'?'Open store':paused?'Resume':'Ⅱ';$('roomPause').setAttribute('aria-label',s.phase!=='open'?'Open store':paused?'Resume shift':'Pause shift');$('roomPause').disabled=tablet.managing;
 $('counterCount').textContent=`${q} waiting`;$('returnCount').textContent=d?`${d} to rewind`:sh?`${sh} to shelve`:s.rewinding.length?'Rewinding…':'All caught up';$('helpCount').textContent=h?`${h} need help`:'All good';$('phoneCount').textContent=`${o} to call`;
 $('goalLabel').textContent=`${s.daily.goalClaimed?'BONUS EARNED':'TODAY’S GOAL'} · ${s.daily.rentals} / ${E.goal(s)} rentals`;$('goalFill').style.width=Math.min(100,s.daily.rentals/E.goal(s)*100)+'%';$('streak').textContent=`✦ ${s.streak%5} / 5 happy streak`;$('crewCount').textContent=s.staff.length;
 $('sceneHint').textContent=s.phase==='planning'?'A new beginning. Open the doors when you’re ready.':s.phase==='closed'?'Another movie night in the books. Plan your next big day.':h?`${REGULARS[s.customers.find(c=>c.stage==='help').regular].name} could use your movie expertise.`:q?'A happy customer is one checkout away.':d?'Those returns won’t rewind themselves.':`Tonight’s buzz: ${E.eventFor(s).genre.toLowerCase()} movies.`;
 document.querySelectorAll('[data-patience]').forEach(el=>{const c=s.customers.find(v=>v.id===Number(el.dataset.patience));if(c){el.style.width=Math.max(0,100*(1-c.wait/c.patience))+'%';el.style.background=c.wait/c.patience>.7?'var(--red)':'var(--teal)';}});
 document.querySelectorAll('[data-deck]').forEach(el=>{const j=s.rewinding[Number(el.dataset.deck)];if(j)el.textContent=Math.max(0,Math.ceil(j.left))+'s';});
 document.querySelectorAll('[data-ready]').forEach(el=>el.textContent=s.stock[Number(el.dataset.ready)].ready);document.querySelectorAll('[data-owned]').forEach(el=>el.textContent=s.stock[Number(el.dataset.owned)].owned);document.querySelectorAll('[data-stock]').forEach(el=>el.textContent=s.snacks[el.dataset.stock].stock);
 document.querySelectorAll('[data-buy-movie]').forEach(el=>el.disabled=s.cash<MOVIES[Number(el.dataset.buyMovie)].cost||E.copies(s)>=E.capacity(s));
 if($('capacityText'))$('capacityText').textContent=`${E.copies(s)} / ${E.capacity(s)} copies · ${s.loans.length} rented out`;
}
function brief(){const ev=E.eventFor(s);return `<div class="brief"><small>THE NEIGHBORHOOD BUZZ</small><h3>${esc(ev.title)}</h3><p>${esc(ev.text)}</p></div>`;}
function empty(icon,title,text){return `<div class="empty-state"><div class="big-icon">${icon}</div><h3>${title}</h3><p>${text}</p></div>`;}
function customerHead(c){const r=REGULARS[c.regular];return `<div class="customer-head"><div class="avatar" style="color:${r.color}">${['◉','◒','❋','◈'][c.regular%4]}</div><div><strong>${esc(c.name)}</strong><small>${esc(r.label)} · Budget ${money(c.budget)}</small></div></div><p class="regular-story">“${esc(X.storyLine(s,c.regular))}”</p><div class="patience" aria-label="Customer patience"><i data-patience="${c.id}" style="width:${100*(1-c.wait/c.patience)}%"></i></div>`;}
function renderWork(force=false){
 if(!force&&tablet.pointerHeld)return;
 const sig=JSON.stringify([station,s.phase,s.day,s.customers.map(c=>[c.id,c.stage,c.movie]),s.stock.map(v=>[v.dirty,v.shelve,v.ready]),s.rewinding.map(j=>j.movie),E.overdue(s).map(l=>[l.id,l.called]),selectedCustomer]);if(sig===workSig)return;workSig=sig;
 const names={counter:['LET’S MAKE MOVIE NIGHT','The checkout counter'],returns:['BE KIND. REWIND.','The return desk'],floor:['EVERYONE HAS A FAVORITE','A little movie magic'],phone:['THE LAST COPY IS OUT THERE','Overdue reminders']};$('panelEyebrow').textContent=names[station][0];$('panelTitle').textContent=names[station][1];$('panelBadge').textContent=s.phase==='open'?'YOUR SHIFT':'PLAN YOUR DAY';let html='';
 if(station==='counter'){
  const q=s.customers.filter(c=>c.stage==='checkout');html=q.map(c=>{const m=MOVIES[c.movie],n=c.snack&&s.snacks[c.snack],snack=n&&n.stock>0&&n.price<=c.snackBudget?SNACKS.find(v=>v.id===c.snack):null;return `<article class="customer-card">${customerHead(c)}<div class="customer-movie">${cover(m)}<div><strong>${esc(m.title)}</strong><small>One-night rental · ${money(E.price(s,m))}</small>${snack?`<small>${snack.icon} + ${snack.name} · ${money(n.price)}</small>`:''}</div></div><button class="primary full" data-action="checkout" data-id="${c.id}">Check out · ${money(E.price(s,m)+(snack?n.price:0))}</button></article>`;}).join('');
  if(!q.length)html=empty('▤',s.phase==='open'?'Ready for movie night':'The keys are yours',s.phase==='open'?'Customers are browsing. Help them choose a film or catch up on returns.':'Start with 24 tapes, a trusty rewinder, and a neighborhood full of movie lovers. Open the store to begin.');html+=brief();if(s.phase!=='open')html+=`<div class="brief"><small>ONE GOOD SHIFT AT A TIME</small><p>Rent ${E.goal(s)} movies for a <b class="gold">$${30+s.day*3} bonus</b>. Five quick checkouts in a row earn another $8.</p></div>`;
 }
 if(station==='returns'){
  html=`<div><div class="note">Start a tape, then work somewhere else while it rewinds. Rewound tapes must go back on the shelf.</div>`;
  for(let i=0;i<1+(s.upgrades.rewinders||0);i++){const j=s.rewinding[i];html+=`<div class="deck ${j?'running':''}" style="margin-top:12px"><div class="deck-top"><span>DANDY-DECK ${i+1}</span><span>${s.upgrades.turbo?'TURBO':'VHS'}</span></div><div class="deck-window"><i class="reel"></i><span data-deck="${i}">${j?Math.ceil(j.left)+'s':'READY'}</span><i class="reel"></i></div><p>${j?esc(MOVIES[j.movie].title):'Insert an unrewound tape below.'}</p></div>`;}
  const pending=s.stock.map((st,i)=>({st,i})).filter(v=>v.st.shelve>0||v.st.dirty>0);if(!pending.length)html+=empty('✦','The bins are clear','New returns arrive during the shift. You can call overdue renters to get wanted movies back sooner.');
  for(const {st,i} of pending)html+=`<div class="return-card"><div><strong>${esc(MOVIES[i].title)}</strong><small>${st.dirty} unrewound · ${st.shelve} ready to shelve</small></div>${st.shelve?`<button class="primary" data-action="shelve" data-id="${i}">Shelve</button>`:`<button data-action="rewind" data-id="${i}" ${s.rewinding.length>=1+(s.upgrades.rewinders||0)?'disabled':''}>Rewind</button>`}</div>`;html+='</div>';
 }
 if(station==='floor'){
  const help=s.customers.filter(c=>c.stage==='help');if(!help.length)html=empty('✦','Good movies find good people','Customers with a question mark need a recommendation. Match their preferred genre and budget.');
  else{if(!help.some(c=>c.id===selectedCustomer))selectedCustomer=help[0].id;const c=help.find(v=>v.id===selectedCustomer);const r=REGULARS[c.regular];html=`<div><div class="customer-card">${customerHead(c)}<p class="quote">“${esc(c.genre===r.genre?r.quote:`I’m in the mood for ${c.genre.toLowerCase()} tonight. What do you have?`)}”</p><span class="pill">WANTS ${c.genre.toUpperCase()}</span></div>`;
   if(help.length>1)html+=`<div class="filters">${help.map(v=>`<button data-action="select-customer" data-id="${v.id}" class="${v.id===selectedCustomer?'active':''}">${esc(v.name)}</button>`).join('')}</div>`;
   const choices=MOVIES.filter(m=>m.genre===c.genre&&s.stock[m.id].ready>0);html+='<h4>ON YOUR SHELVES</h4>';
   if(!choices.length)html+=`<p class="note">No ${c.genre.toLowerCase()} movies are ready. Rewind a return, call a renter, or buy a copy in the catalog.</p>`;
   html+=choices.map(m=>`<div class="mini-movie">${cover(m)}<div><strong>${esc(m.title)}</strong><small>${money(E.price(s,m))} · ${s.stock[m.id].ready} ready${E.price(s,m)>c.budget?' · over budget':''}</small></div><button data-action="recommend" data-id="${m.id}" ${E.price(s,m)>c.budget?'disabled':''}>Suggest</button></div>`).join('');html+='</div>';
  }
 }
 if(station==='phone'){
  const loans=E.overdue(s);html=`<div><p class="note">A friendly call gets the movie back soon. A firm call adds a $1.50 fee but costs a little goodwill. Waiving the fee earns extra goodwill.</p>`;
  if(!loans.length)html+=empty('☎','Nobody to chase','All outstanding rentals are still within their rental period.');
  html+=loans.map(l=>`<div class="customer-card" style="margin-top:13px"><div class="customer-head"><div class="avatar">☎</div><div><strong>${esc(l.name)}</strong><small>${Math.max(1,s.day-l.dueDay)} day${s.day-l.dueDay===1?'':'s'} overdue</small></div></div><p class="quote">${esc(MOVIES[l.movie].title)}</p>${l.called?'<p class="note teal">Called · on the way back to the store.</p>':`<div class="action-row"><button data-action="call" data-id="${l.id}" data-tone="friendly">Friendly</button><button data-action="call" data-id="${l.id}" data-tone="firm">Firm + fee</button><button data-action="call" data-id="${l.id}" data-tone="waive">Waive fee</button></div>`}</div>`).join('');html+='</div>';
 }
 $('workContent').innerHTML=html;
}
function renderBusiness(){
 document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let html='';
 if(tab==='neighborhood')html=renderNeighborhood(s,neighborhood,cover);
 if(tab==='catalog'){
  const list=MOVIES.filter(m=>(genre==='All'||m.genre===genre)&&(!ownedOnly||s.stock[m.id].owned>0)&&(!search||m.title.toLowerCase().includes(search.toLowerCase())));
  html=`<div class="section-head"><div><h2>Big stories. Small plastic boxes.</h2><p id="capacityText">${E.copies(s)} / ${E.capacity(s)} copies · ${s.loans.length} rented out</p></div><div class="filters"><input id="movieSearch" placeholder="Find a movie…" aria-label="Search movie titles" value="${esc(search)}"><button data-action="owned-filter" class="${ownedOnly?'active':''}">Owned only</button>${['All',...GENRES].map(g=>`<button class="${g===genre?'active':''}" data-action="genre" data-genre="${g}">${g}</button>`).join('')}</div></div><div class="movie-grid">`;
  html+=list.map(m=>{const st=s.stock[m.id],locked=m.unlock>s.day,hot=E.eventFor(s).genre===m.genre;return `<article class="movie-card ${locked?'locked':''}">${cover(m)}<div class="movie-info"><h3>${esc(m.title)}</h3><div class="stockline"><b><span data-ready="${m.id}">${st.ready}</span> ready</b> / <span data-owned="${m.id}">${st.owned}</span> owned ${hot?'· <span class="gold">HOT</span>':''}</div><div class="buyrow"><span>${locked?`Arrives day ${m.unlock}`:money(m.cost)+'/copy'}</span>${locked?'':`<button data-action="buy-movie" data-id="${m.id}" data-buy-movie="${m.id}" ${s.cash<m.cost||E.copies(s)>=E.capacity(s)?'disabled':''}>Buy copy +</button>`}</div></div></article>`;}).join('');html+='</div>';if(!list.length)html+=empty('▤','No titles found','Try a different title or genre.');
 }
 if(tab==='crew'){
  const payroll=s.staff.filter(e=>e.scheduled).reduce((a,e)=>a+e.wage*8,0),cap=X.staffCap(s);html=`<div class="section-head"><div><h2>A little help goes a long way.</h2><p>${s.staff.length} / ${cap} employees · Scheduled full-shift wages: <span class="gold">${money(payroll)}</span></p></div><span class="pill">PAYROLL IS PAID AT CLOSING</span></div>`;
  if(!s.staff.length)html=html+empty('✦','Your first hire is a big deal','Hire a cashier, a movie expert, or someone who loves a well-organized return bin. You can always jump in and help.');
  html+='<div class="crew-grid">'+s.staff.map(e=>{const c=CANDIDATES[e.id];return `<article class="staff-card"><h3>${c.name}</h3><div class="role">${c.role}</div><p>${c.trait}</p><div class="field-row"><label for="job-${e.id}">Job priority</label><select id="job-${e.id}" data-change="assignment" data-id="${e.id}">${[['checkout','Cashier'],['floor','Floor clerk'],['returns','Returns & calls'],['all','Help everywhere']].map(([id,n])=>`<option value="${id}" ${id===e.assignment?'selected':''}>${n}</option>`).join('')}</select></div><div class="field-row"><label for="wage-${e.id}">Hourly wage</label><input id="wage-${e.id}" data-change="wage" data-id="${e.id}" type="number" min="3" max="20" step=".5" value="${e.wage}"></div><div class="field-row"><label><input type="checkbox" data-change="scheduled" data-id="${e.id}" ${e.scheduled?'checked':''}>Work this shift</label><span class="muted">${money(e.wage*8)}/day</span></div>${trainingCard(e)}<div class="morale">Morale ${Math.round(e.morale)}% · Typical wage ${money(c.expected)}/hr</div><div class="track"><i style="width:${e.morale}%;background:var(--teal)"></i></div><div class="action-row"><button data-action="bonus" data-id="${e.id}">Give $15 bonus</button><button class="ghost danger" data-action="dismiss-staff" data-id="${e.id}">Let go</button></div></article>`;}).join('')+'</div>';
  html+=`<div class="candidate-section"><h3>Applicants on the bulletin board</h3><p class="note" style="margin:0 0 14px">Hiring costs $35. Offer within $2 of their expected wage to hire them. Wages affect morale and retention; underpaid staff may leave.</p><div class="crew-grid">`+CANDIDATES.filter(c=>!s.staff.some(e=>e.id===c.id)).map(c=>`<article class="staff-card"><h3>${c.name}</h3><div class="role">${c.role}</div><p>${c.trait}</p><div class="field-row"><label for="offer-${c.id}">Your hourly offer</label><input id="offer-${c.id}" type="number" min="3" max="20" step=".5" value="${c.expected}"></div><p class="note">Hopes for ${money(c.expected)}/hour · ${money(c.expected*8)} per full shift</p><button class="full" data-action="hire" data-id="${c.id}" ${s.cash<35||s.staff.length>=cap?'disabled':''}>Hire ${c.name} · $35 setup</button></article>`).join('')+'</div></div>';
 }
 if(tab==='snacks'){
  html=`<div class="section-head"><div><h2>Movie-night essentials.</h2><p>Adjust rental rates and snack prices. Customers have individual budgets; empty shelves mean missed sales.</p></div></div><div class="pricing-row"><label>Classic rental <input data-change="price" data-kind="classic" type="number" min="1" max="9" step=".25" value="${s.prices.classic}" aria-label="Classic rental price"></label><label>New release <input data-change="price" data-kind="new" type="number" min="1" max="9" step=".25" value="${s.prices.new}" aria-label="New release rental price"></label><span class="note">One-night rentals. Starter titles are classics; day 2 onward adds new releases.</span></div><div class="snack-grid">`+SNACKS.map(n=>`<article class="snack-card"><div class="snack-icon">${n.icon}</div><h3>${n.name}</h3><p><b data-stock="${n.id}">${s.snacks[n.id].stock}</b> in stock · Cost ${money(n.cost/10)} each</p><div class="field-row"><label for="snack-${n.id}">Sale price</label><input id="snack-${n.id}" data-change="snack-price" data-kind="${n.id}" type="number" min=".5" max="5" step=".25" value="${s.snacks[n.id].price}"></div><button style="margin-top:18px" class="full" data-action="buy-snacks" data-kind="${n.id}">Order 10 · ${money(n.cost)}</button></article>`).join('')+'</div><p class="note">Snacks sell at checkout when the customer wants one, the price fits their budget, and you have stock. A higher price is not always a higher profit.</p>';
 }
 if(tab==='upgrades'){
  html=`<div class="section-head"><div><h2>From corner shop to local legend.</h2><p>Every improvement changes what your store can handle. Build a flagship, then open up to three managed neighborhood branches.</p></div></div><div class="upgrade-grid">`+UPGRADES.map((u,i)=>{const qty=s.upgrades[u.id]||0,done=qty>=u.max,locked=u.id==='branch'&&!s.upgrades.store;return `<article class="upgrade-card"><div class="upgrade-icon">${['⏪','ϟ','▥','✧','▰','▣','⌂','♜'][i]}</div><h3>${u.title}</h3><p>${u.desc}</p><button data-action="upgrade" data-kind="${u.id}" ${done||locked||s.cash<u.cost?'disabled':''}>${done?'Installed ✓':locked?'Needs flagship renovation':`${money(u.cost)}${u.max>1?` · ${qty}/${u.max} built`:''}`}</button></article>`;}).join('')+'</div>';
 }
 if(tab==='decor'){
  html=`<div class="section-head"><div><h2>Make it yours.</h2><p>Your name over the door. Your favorite little corner of town.</p></div></div><div class="customize-name"><label for="storeName">Store name</label><input id="storeName" maxlength="28" value="${esc(s.decor.name)}"><button data-action="rename">Update sign · free</button></div><h3>Neon sign color · free</h3><div class="action-row">${[['rose','Rose pink'],['mint','Video mint'],['gold','Golden hour']].map(([id,label])=>`<button data-action="sign-color" data-kind="${id}" aria-pressed="${s.decor.sign===id}" class="${s.decor.sign===id?'primary':''}">${label}</button>`).join('')}</div><h3>Little things that make it home</h3><div class="upgrade-grid">${[['plants','A little greenery',45,'Two leafy plants brighten the entrance.'],['rug','Movie-night rug',65,'A warm patterned rug for the center aisle.'],['arcade','Retro arcade cabinet',150,'Give the store its own glowing arcade corner.']].map(([id,label,cost,desc])=>`<article class="upgrade-card"><h3>${label}</h3><p>${desc}</p><button data-action="decorate" data-kind="${id}" ${s.decor[id]||s.cash<cost?'disabled':''}>${s.decor[id]?'Installed ✓':money(cost)}</button></article>`).join('')}</div><p class="note">Decorations are cosmetic. Equipment and comfort upgrades are in Grow the store.</p>`;
 }
 if(tab==='ledger'){
  html=`<div class="section-head"><div><h2>Every rental has a story.</h2><p>${s.totalRentals} lifetime rentals · Best happy streak: ${s.bestStreak} · ${s.lifetime.rewinds} tapes rewound · ${s.lifetime.calls} reminder calls</p></div><button data-action="report" ${!s.report?'disabled':''}>Last shift receipt</button></div>`;
  html+=`<div class="pricing-row"><span>Today’s sales: <b class="gold">${money(s.daily.revenue)}</b></span><span>Wages accrued: <b>${money(s.daily.payroll)}</b></span><span>Customers lost: <b>${s.daily.lost}</b></span><span>Outstanding rentals: <b>${s.loans.length}</b></span></div>`;
  if(s.history.length)html+='<div class="table-wrap"><table class="history-table"><thead><tr><th>DAY</th><th>RENTALS</th><th>REVENUE</th><th>BONUSES</th><th>PAYROLL</th><th>NET CASH CHANGE</th></tr></thead><tbody>'+[...s.history].reverse().map(r=>`<tr><td>${r.day}</td><td>${r.rentals}</td><td>${money(r.revenue)}</td><td>${money(r.bonus)}</td><td>${money(r.payroll)}</td><td class="${r.profit>=0?'teal':'danger'}">${r.profit<0?'−':''}${money(Math.abs(r.profit))}</td></tr>`).join('')+'</tbody></table></div>';
  html+='<div class="log">'+s.log.slice(0,18).map(l=>`<div><small>DAY ${l.day}</small>${esc(l.text)}</div>`).join('')+'</div>';
 }
 if(tab==='upgrades')html+='<div class=brief><h3>Earn visible store milestones</h3><p>A staff-picks wall, deluxe snack counter, screening corner and collector’s annex.</p><button data-action=xp-section data-kind=milestones>View milestones</button></div>';
 $('businessContent').innerHTML=html;tablet.enhanceNumbers($('businessContent'));bizDirty=false;
}
function renderAll(){workSig='';updateHud();renderWork(true);renderBusiness();}
function introduction(){showModal(`<div class="intro-banner">1993. A LITTLE STORE. A BIG POSSIBILITY.</div><h2>Welcome to Rewind & Dandy.</h2><p>You’ve got the keys, 24 tapes, and $245 in the till. The neighborhood is counting on you for a good movie night.</p><div class="intro-steps"><div><strong>1 · Make their night</strong><span>Help customers choose a movie, then check them out at the counter. Snacks sell with rentals.</span></div><div><strong>2 · Keep tapes moving</strong><span>Rewind returns, put them back on the shelf, and call overdue renters.</span></div><div><strong>3 · Make smart bets</strong><span>Buy extra copies of hot films, set prices, and keep snacks stocked.</span></div><div><strong>4 · Build your crew</strong><span>Hire multiple workers, set hourly pay, and choose their jobs. Wages are paid at closing.</span></div></div><p class="note">A shift takes eight minutes at 1×. Use 2× or 4× when things are quiet. Tap customers or objects in the store to open their controls. Shelves open the catalog, the snack rack opens prices, and your sign opens decorations. Drag to pan and pinch to zoom. Use ⛶ for full screen, and ☰ for all store controls. × closes a panel. Tap Neighbors for regulars’ stories, movie nights, rare-tape collections and store milestones. Train employees from Staff once they have completed enough jobs. Visitors start on day 3. The first three days ease you in with slower arrivals and extra patient customers. Manage pauses the shift. On a keyboard, Space pauses and 1–4 switch jobs. Dialogs pause the game; leaving the app pauses until you resume. Progress saves on this device.</p><div class="modal-actions"><button class="primary" data-action="start">Take the keys →</button><button data-action="enable-sound">Enable music & sounds</button></div>`);}
function settings(){showModal(`<div class="intro-banner">THE BACK OFFICE</div><h2>Save & settings</h2><p>Progress is stored in this browser on this device. Export a save to move your store to another device or keep a backup.</p><div class="file-tools"><button data-action="save">Save now</button><button data-action="export">Export save</button><button data-action="import">Import save</button></div><div class="volume-controls"><label>Music <input type="range" min="0" max="1" step=".05" value="${audio.music}" data-change="music" aria-label="Music volume"></label><label>Sound effects <input type="range" min="0" max="1" step=".05" value="${audio.effects}" data-change="effects" aria-label="Sound effects volume"></label><button data-action="enable-sound">${audio.enabled?'Turn sound off':'Turn sound on'}</button></div><p class="note">${saveAvailable?'Autosave is available.':'Local saving is unavailable in this browser. Please export backups.'} Your store pauses whenever this window is open. Tap ⛶ in the corner for full screen, then hold your tablet sideways. Portrait and landscape both work.</p><button class="danger" data-action="reset-confirm">Start a new store…</button>`);}
function showReport(){const r=s.report;if(!r)return;showModal(`<div class="intro-banner">REWIND & DANDY · END-OF-DAY RECEIPT</div><h2>That’s a wrap, day ${r.day}.</h2><p>${r.rentals>=r.goal?'You made movie night happen. Your daily goal bonus is in the till.':'Every shift teaches you something. A few small changes can make tomorrow your best day yet.'}</p><div class="report-grid"><div><small>MOVIES RENTED</small><strong>${r.rentals}</strong></div><div><small>SNACKS SOLD</small><strong>${r.snackSales}</strong></div><div><small>CUSTOMERS LOST</small><strong>${r.lost}</strong></div></div><div class="receipt"><div><span>Rental, snack & branch sales</span><span>${money(r.revenue)}</span></div><div><span>Goals & happy streak bonuses</span><span>+${money(r.bonus)}</span></div><div><span>Purchases & improvements</span><span>−${money(r.supplies)}</span></div><div><span>Staff wages</span><span>−${money(r.payroll)}</span></div><div><span>Rent & branch operating costs</span><span>−${money(r.rent)}</span></div><div class="total"><span>Net cash change</span><strong>${r.profit<0?'−':'+'}${money(Math.abs(r.profit))}</strong></div></div>${r.rescue?`<p class="inline-alert">Community rescue: +${money(r.rescue)}. Reputation −8. Review your costs before the next shift.</p>`:''}<div class="brief"><small>TOMORROW’S BUZZ</small><h3>${EVENTS[r.day%7].title}</h3><p>${EVENTS[r.day%7].text}</p>${r.day===1||r.day===3||r.day===6?'<p class="gold">Fresh titles arrive tomorrow. Check the catalog!</p>':''}</div><div class="modal-actions"><button class="primary" data-action="open">One more day →</button><button data-action="plan">Plan before opening</button></div>`);}
modal.addEventListener('close',()=>{if(s.phase==='closed'){E.prepareDay(s);lastPhase=s.phase;lastDay=s.day;renderAll();save();}});
function movieDetail(id){const m=MOVIES[id],st=s.stock[id];showModal(`<div class="movie-detail">${cover(m)}<div><span class="intro-banner">${m.genre.toUpperCase()} · ${E.isNew(m)?'NEW RELEASE':'VIDEO CLASSIC'}</span><h2>${esc(m.title)}</h2><blockquote>“${esc(m.tagline)}”</blockquote><p>${esc(m.synopsis)}</p><p class="note">${st.ready} ready · ${st.dirty} unrewound · ${st.shelve} awaiting shelving · ${st.owned} owned<br>${st.rentals} lifetime rentals · Appeal ${m.demand}/100</p><p>Rental: <span class="gold">${money(E.price(s,m))}</span> · Purchase: ${money(m.cost)}</p><button class="primary" data-action="buy-movie" data-id="${id}" ${s.day<m.unlock||s.cash<m.cost||E.copies(s)>=E.capacity(s)?'disabled':''}>${s.day<m.unlock?`Available day ${m.unlock}`:'Buy another copy'}</button></div></div>`);}
function act(action,el){const id=Number(el.dataset.id),kind=el.dataset.kind;let ok=true;
 switch(action){
  case 'xp-section':neighborhood=kind;tab='neighborhood';tablet.setView('manage');renderBusiness();return;
  case 'xp-story':ok=X.claimStory(s,id);break;
  case 'xp-night':ok=X.bookNight(s,kind);break;
  case 'xp-train':ok=X.train(s,id,kind);break;
  case 'xp-milestone':ok=X.milestone(s,kind);break;
  case 'xp-guest':ok=X.guestAction(s,kind);break;
  case 'room-fullscreen':dismiss();tablet.fullscreen();return;
  case 'room-camera':scene.resetCamera(true);dismiss();return;
  case 'room-zoom':scene.resetCamera();scene.camera.zoom=1.2;dismiss();return;
  case 'room-speed':$('speedBtn').onclick();roomMenu();return;
  case 'room-manage':dismiss();roomAction(kind);return;
  case 'room-help':introduction();return;
  case 'room-settings':settings();return;
  case 'rename':s.decor.name=$('storeName').value.trim().slice(0,28)||'Rewind & Dandy';toast('Your name is over the door.');break;
  case 'sign-color':if(['rose','mint','gold'].includes(kind))s.decor.sign=kind;break;
  case 'decorate':{const cost={plants:45,rug:65,arcade:150}[kind];if(cost&&!s.decor[kind]&&s.cash>=cost){s.cash-=cost;s.daily.expenses+=cost;s.decor[kind]=true;toast('A little more you. Decoration installed.');}else ok=false;break;}
  case 'start':s.seenIntro=true;dismiss();save();return;
  case 'open':openStore();return;
  case 'plan':dismiss();paused=true;tab='catalog';tablet.setView('manage');renderAll();return;
  case 'checkout':{const r=E.checkout(s,id);if(r.ok)floatCash(r.amount);else toast(r.text);break;}
  case 'rewind':ok=E.rewind(s,id);if(ok)audio.fx('rewind');break;
  case 'shelve':ok=E.shelve(s,id);if(ok){audio.fx('click');toast('Back on the shelf. Ready for movie night.');}break;
  case 'recommend':{const r=E.recommend(s,selectedCustomer,id);toast(r.text);if(r.ok){selectedCustomer=null;audio.fx('click');}break;}
  case 'select-customer':selectedCustomer=id;workSig='';renderWork();return;
  case 'call':ok=E.callRenter(s,id,el.dataset.tone);break;
  case 'buy-movie':ok=E.buyMovie(s,id);if(!ok)toast(E.copies(s)>=E.capacity(s)?'Shelves are full. Add an aisle to increase capacity.':'Not enough cash, or this title has not arrived.');else if(modal.open)movieDetail(id);break;
  case 'buy-snacks':ok=E.buySnacks(s,kind);if(ok)toast(`Ten ${kind} added to your snack rack.`);break;
  case 'upgrade':ok=E.upgrade(s,kind);break;
  case 'hire':{const offer=Number($('offer-'+id).value);ok=E.hire(s,id,offer);if(!ok)toast(offer<CANDIDATES[id].expected-2?`${CANDIDATES[id].name} hopes for a better offer. Try at least ${money(CANDIDATES[id].expected-2)}/hour.`:'Check your cash and employee capacity.');break;}
  case 'bonus':ok=E.bonus(s,id);if(ok)toast(`${CANDIDATES[id].name}: “Thanks! That means a lot.”`);break;
  case 'dismiss-staff':showModal(`<h2>Let ${CANDIDATES[id].name} go?</h2><p>They will stop working immediately. Wages already earned are still paid at closing.</p><div class="modal-actions"><button class="danger" data-action="confirm-dismiss" data-id="${id}">Let them go</button><button data-action="close">Keep on the team</button></div>`);return;
  case 'confirm-dismiss':s.staff=s.staff.filter(e=>e.id!==id);dismiss();break;
  case 'movie':movieDetail(id);return;
  case 'genre':genre=el.dataset.genre;renderBusiness();return;
  case 'owned-filter':ownedOnly=!ownedOnly;renderBusiness();return;
  case 'report':showReport();return;
  case 'save':save();toast('Your store is saved on this device.');return;
  case 'export':{const blob=new Blob([JSON.stringify({...s,notices:[]},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`movie-rental-empire-day-${s.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  case 'import':$('importInput').click();return;
  case 'enable-sound':if(audio.enabled){audio.disable();$('soundBtn').textContent='Sound off';}else audio.enable().then(ok=>{if(ok){$('soundBtn').textContent='Sound on';audio.fx('door');}else toast('Audio is not supported in this browser.');}).catch(()=>toast('Tap Sound on again to enable audio.'));if($('modalContent').textContent.includes('Save & settings'))settings();return;
  case 'reset-confirm':showModal(`<h2>Start a new store?</h2><p>This replaces the save on this device. Export a backup first if you want to keep your current store.</p><div class="modal-actions"><button data-action="export">Export current save</button><button class="danger" data-action="reset">Start fresh</button><button data-action="close">Cancel</button></div>`);return;
  case 'reset':s=E.fresh();paused=true;lastDay=1;lastPhase='planning';scene.people.clear();save();renderAll();introduction();return;
  case 'close':dismiss();return;
 }
 if(!ok&&!['buy-movie','hire'].includes(action))toast(action.startsWith('xp-')?'Check the activity’s unlock, funds, space, or progress requirements.':'Not enough cash or no available space for that action.');workSig='';renderAll();flush();save();
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){act(b.dataset.action,b);return;}const st=e.target.closest('[data-station]');if(st)setStation(st.dataset.station);const t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;renderBusiness();}});
document.addEventListener('change',e=>{const el=e.target,type=el.dataset.change,id=Number(el.dataset.id),kind=el.dataset.kind;let valid=true;
 if(type==='assignment'){const emp=s.staff.find(v=>v.id===id);if(emp&&['checkout','floor','returns','all'].includes(el.value))emp.assignment=el.value;}
 if(type==='wage')valid=E.setWage(s,id,el.value);
 if(type==='scheduled'){const emp=s.staff.find(v=>v.id===id);if(emp){emp.scheduled=el.checked;if(s.phase==='open')emp.active=el.checked;}}
 if(type==='price'){const n=Number(el.value);if(Number.isFinite(n)&&n>=1&&n<=9)s.prices[kind]=n;else valid=false;}
 if(type==='snack-price'){const n=Number(el.value);if(Number.isFinite(n)&&n>=.5&&n<=5)s.snacks[kind].price=n;else valid=false;}
 if(type==='music')audio.music=Number(el.value);if(type==='effects')audio.effects=Number(el.value);
 if(type&&!['music','effects'].includes(type)){if(!valid)toast('Enter a value within the displayed range.');refreshAfterInput();save();}
});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='movieSearch'){search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;renderBusiness();const input=$('movieSearch');if(input){input.focus();input.setSelectionRange(pos,pos);}},240);}if(['music','effects'].includes(e.target.dataset.change))audio[e.target.dataset.change]=Number(e.target.value);});
$('roomMenu').onclick=roomMenu;$('roomFull').onclick=()=>tablet.fullscreen();$('roomPause').onclick=()=>tablet.onAction('pause');$('closeWork').onclick=()=>document.documentElement.classList.remove('work-open');$('closeBusiness').onclick=()=>tablet.setView('play');$('openBtn').onclick=openStore;$('pauseBtn').onclick=()=>{paused=!paused;updateHud();};$('speedBtn').onclick=()=>{speed=speed===1?2:speed===2?4:1;updateHud();};$('helpBtn').onclick=introduction;$('settingsBtn').onclick=settings;$('closeModal').onclick=dismiss;$('saveBtn').onclick=()=>{save();toast('Progress saved.');};$('viewBtn').onclick=()=>scene.resetCamera(!scene.camera.overview);$('soundBtn').onclick=()=>act('enable-sound',$('soundBtn'));
$('importInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Too large');const parsed=JSON.parse(await file.text());if(!E.validate(parsed))throw Error('Invalid save');s=parsed;normalizeDecor();X.ensure(s);s.notices=[];paused=true;lastPhase=s.phase;lastDay=s.day;scene.people.clear();save();dismiss();renderAll();toast('Store restored. Resume when you’re ready.');}catch{toast('That file is not a valid Movie Rental Empire save. Your current store is unchanged.');}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea'))return;if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action="movie"]')){e.preventDefault();movieDetail(Number(e.target.dataset.id));return;}if(modal.open)return;if(e.key==='Escape'){document.documentElement.classList.remove('work-open');tablet.setView('play');return;}if(e.code==='Space'){e.preventDefault();if(s.phase==='open'){paused=!paused;updateHud();}}if(['1','2','3','4'].includes(e.key))setStation(['counter','returns','floor','phone'][Number(e.key)-1]);});
document.addEventListener('visibilitychange',()=>{if(document.hidden){paused=true;save();audio.ctx?.suspend();}else if(audio.enabled)audio.ctx?.resume();last=performance.now();});window.addEventListener('pagehide',save);
function frame(now){const dt=Math.min(.1,(now-last)/1000||0);last=now;if(!document.hidden){if(!paused&&!modal.open&&!tablet.managing)E.tick(s,dt*speed);if(tablet.sceneVisible&&(!tablet.active||now-tablet.lastDraw>=33)){scene.draw(s,now);tablet.lastDraw=now;}acc+=dt;saveAcc+=dt;if(acc>=.3){acc=0;updateHud();renderWork();flush();if(lastPhase!==s.phase||lastDay!==s.day){if(s.phase==='closed'){paused=true;showReport();renderBusiness();save();}lastPhase=s.phase;lastDay=s.day;}}if(saveAcc>=5){saveAcc=0;save();}}requestAnimationFrame(frame);}
renderAll();if(!s.seenIntro)introduction();else if(s.phase==='closed')showReport();requestAnimationFrame(frame);
